INSERT INTO feature VALUES('cell-rewriting','rewriting','Cell rewriting over the command IL',NULL,'implemented','notable',NULL,'Rules become cells over command patterns, matched, unified and anti-unified under a reduction order and admitted only when left-linear; a right side''s copies are counted, not refused. A wire, a metavariable that only the right side holds, takes a fresh name at each firing, so two firings write two wires.','theory-cell-complexes','crates/theory-cell-complexes/tests/subst.rs crates/theory-cell-complexes/tests/order.rs',NULL,NULL);
